const row = $input.first()?.json;

if (!row || !row.cliente_id) {
  return [{
    json: {
      encontrado: false,
      mensaje: 'No encontré ningún cliente con ese dato. Verifícalo o intenta con el otro (código o teléfono).'
    }
  }];
}

const esRecurrente = (row.total_ordenes || 0) > 0;

return [{
  json: {
    encontrado: true,
    es_nuevo: !esRecurrente,
    es_recurrente: esRecurrente,
    cliente_id: row.cliente_id,
    empresa: row.empresa,
    nombre: row.nombre,
    telefono: row.telefono,
    total_ordenes: row.total_ordenes || 0,
    ultima_compra_fecha: row.ultima_compra_fecha,
    producto_mas_frecuente: row.producto_mas_frecuente_id ? {
      sku: row.producto_mas_frecuente_id,
      nombre: row.producto_mas_frecuente_nombre,
      precio: parseFloat(row.producto_mas_frecuente_precio),
      categoria: row.producto_mas_frecuente_categoria
    } : null
  }
}];
